<template lang="en">
<div class="my-popups">
    <div class="modal d-block">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">{{$t('Return')}}:{{ItemData.Name}}
                    </h5>
                    <button v-on:click="closeReturn" type="button" class="close" data-original-title="Close"><em class="fa fa-times"></em>
                    </button>
                </div>
                <div class="border p-3">
                    <dynamic-form lang="en" ref="ReturnForm" :buttons="buttons" :schema="FormSchema" v-on:OnSubmit="onSubmit"></dynamic-form>
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>

import DataService from '../../service/DataService';

export default {
    props: {
        ItemData: {
            type: Array,
            required: true
        }
    },
    data() {
        return {
            IsShowAddNamePopup: false,
            Title: '',
            FormSchema: [{
                    layoutType: "double",
                    Data: [{
                            astype: "TextField",
                            label: this.$t('Product'),
                            name: "Product",
                            value: "",
                            placeholder: "",
                            config: {
                                options: [],

                            },
                            disabled: true,
                        },
                        {
                            astype: "TextField",
                            label: this.$t('Unique Name'),
                            name: "10/12/2022 12:AM",
                            value: "",
                            placeholder: "",
                            disabled: true,

                        },
                        {
                            astype: "DateField",
                            label: this.$t('AssignedFrom'),
                            name: "10/12/2022 12:AM",
                            value: '',
                            placeholder: "10/12/2022 12:AM",
                            config: {
                                format: "MM/DD/YYYY"
                            },
                            disabled: true,
                        },

                        {
                            astype: "DateField",
                            label: this.$t('Assigned Till'),
                            name: "Assigned Till",
                            value: '',
                            placeholder: "M/D/YYYY",
                            config: {
                                format: "MM/DD/YYYY"
                            },
                            disabled: true,
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Reason'),
                            name: "Reason",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": true,
                                max: 250
                            },
                            config: {
                                options: [],
                                onChange: () => {}

                            },
                        },

                        {
                            astype: "TextField",
                            label: this.$t('Number of Products'),
                            name: "NumberofProducts",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": true,
                                max: 250
                            },
                        }

                    ]
                },

                {
                    layoutType: "single",
                    Data: [{
                        astype: "TextAreaField",
                        label: this.$t('Remarks'),
                        name: "Remarks",
                        value: "",
                        placeholder: ""
                    }, ]
                }
            ],
            buttons: [{
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                },

                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.onCancel
                }
            ],
            UserId: '',
        }
    },
    created: async function () {
        var vm=this;
        vm.UserId=this.GetUserInfo.ID;
        if(vm.ItemData.RELATED_INFO_ID > 0){
             vm.FetchData(); 
        }            
        await vm.GetAssetItemStatusList();
    },
    methods: {
        FetchData: function () {
            var vm = this;
            vm.isLoading = true;
            (vm.FormSchema)[0].Data[0].value = vm.ItemData.name;
            (vm.FormSchema)[0].Data[1].value = vm.ItemData.UNIQUE_NAME;
            (vm.FormSchema)[0].Data[2].value = vm.ItemData.assigned_from;
            (vm.FormSchema)[0].Data[3].value = vm.ItemData.assigned_till;
        },

        async GetAssetItemStatusList() {
            var vm=this;
            var url = `requestFrom=AssetReplace`
            await DataService.GetAssetItemStatusList(url).then(response => {
                this.statusList = response.data;
                this.statusList.forEach((item, index) => {
                    (vm.FormSchema)[0].Data[4].config.options.push({
                        name: item.STATUS_NAME,
                        value: item.STATUS_ID
                    })
                    vm.$refs.ReturnForm.UpdateKeyValue();
                })
            });
        },

        closeReturn: function () {
            this.$parent.closeReturn();
            this.$emit('closeReturn');
        },
        onCancel: function () {
            this.$parent.closeReturn();
            this.$emit('closeReturn');
        },
        
        onSubmit: function (formfields, val) {
            var vm = this;
            vm.isLoading = true;
            let JsonObj = {
                Name: vm.ItemData.name,
                UniqueName: vm.ItemData.UNIQUE_NAME,
                AssignedFrom: vm.ItemData.assigned_from,
                AssignedTill: vm.ItemData.assigned_till,
                NumberOfItems : formfields.NumberofProducts,
                Reason: formfields.Reason,
                Remarks: formfields.Remarks,
                //AssetReplacementType: '',
                RelatedInfoId: vm.ItemData.RELATED_INFO_ID,
                AssetAssignmentId: vm.ItemData.asset_assignment_id,
                AssetAssignmentDetailId: vm.ItemData.assignment_detail_id,
                UserId: vm.UserId,
                // AssetCatalogueId: '',
                // RetrunStatus: ''
            };
            var Jsondata = JSON.stringify(JsonObj);
                DataService.AssetReturn(Jsondata).then(response => {
                    if (response.data != null) {
                        if (response.data.status == 0) {
                            vm.ShowAlert(vm.$t('ReturnRequest'), "success", true, vm.$t('Alert'))                           
                            vm.$parent.GetReturnList();
                            vm.onCancel();
                            // var final = Number(formfields.NumberofProducts) - vm.ItemData.NumberOfItems;
                            // if (final < 0) {
                            //     setButonDisable(formfields.assetAssignmentId, final)
                            // }
                        } else {
                            vm.ShowAlert(vm.$t("ErrorWhileProcessingRequest"), "failure", true, vm.$t('Alert'));
                            vm.onCancel();
                        };
                    }
                    vm.isLoading = false;
                });
            
        },

        // SubmitData: function () {
